import React, { type ReactNode } from 'react';
import { Image, Platform, Pressable, StyleSheet, Text, View } from 'react-native';

import { ShareProgressBar } from '../ShareState/ShareProgressBar';
import { shareBarColorsFrom, type ShareBarColors } from '../ShareState/shareState';
import { DownloadPie } from './DownloadPie';
import { FileViewIcon, type FileViewIconName } from './FileViewIcon';
import {
  EXPANDED_ROW_HEIGHT,
  EXPANDED_THUMB,
  GRID_STATUS_SHRINK,
  GRID_TEXT_GAP,
  GRID_TEXT_SPILL,
  LIST_ROW_HEIGHT,
  LIST_THUMB,
  fitTextSize,
  gridText,
  type FileViewKind,
  type FileTone,
  type FileViewItem,
} from './fileViewLogic';

/**
 * One file, drawn three ways: a line in the list, a row in the expanded list, a tile in the
 * grid. All three take the same file and the same colours, so an app can use these inside a
 * list of its own, or use `FileViews`, which lays them out for it.
 */

/** The colours a view is drawn in. An app passes its own; these are the dark defaults. */
export type FileViewColors = {
  text: string;
  /** Small text that is not a status: a detail, a name that is dimmed. */
  muted: string;
  /** Status colours, by tone. */
  good: string;
  busy: string;
  bad: string;
  /** The square behind a file that has no picture. */
  tile: string;
  /** The icon on that square. */
  glyph: string;
  /** The hairline between rows of the expanded list. */
  line: string;
  /** Every other line of the list view, like a folder in Finder. */
  stripe: string;
  /** The tick of a chosen file. */
  accent: string;
  onAccent: string;
  /** The progress bar. Left out, it is made from `busy` and `good`, so it matches the words. */
  bar?: ShareBarColors;
};

export const DARK_FILE_VIEW_COLORS: FileViewColors = {
  text: '#ffffff',
  muted: 'rgba(255,255,255,0.56)',
  good: '#a8cf3a',
  busy: '#f2b84b',
  bad: '#ff6b6b',
  tile: 'rgba(255,255,255,0.09)',
  glyph: 'rgba(255,255,255,0.88)',
  line: 'rgba(255,255,255,0.08)',
  stripe: 'rgba(255,255,255,0.045)',
  accent: '#a8cf3a',
  onAccent: '#111111',
};

/** The app's own picture for a file (a video frame, its own icon). Return null to get the standard one. */
export type RenderFileThumb<Extra = unknown> = (item: FileViewItem<Extra>, size: number) => ReactNode;

const KIND_ICON: Record<FileViewKind, FileViewIconName> = {
  image: 'kind-image',
  video: 'kind-video',
  audio: 'kind-audio',
  document: 'kind-document',
  folder: 'kind-folder',
  file: 'kind-file',
};

function toneColor(tone: FileTone | undefined, colors: FileViewColors): string {
  if (tone === 'good') return colors.good;
  if (tone === 'busy') return colors.busy;
  if (tone === 'bad') return colors.bad;
  return colors.muted;
}

function barColors(colors: FileViewColors): ShareBarColors {
  return colors.bar ?? shareBarColorsFrom({ busy: colors.busy, good: colors.good });
}

function spoken(item: FileViewItem): string {
  return item.status ? `${item.name}, ${item.status}` : item.name;
}

// ---------------------------------------------------------------------------------------------
// The picture
// ---------------------------------------------------------------------------------------------

export type FileThumbProps<Extra = unknown> = {
  item: FileViewItem<Extra>;
  size: number;
  radius?: number;
  colors?: FileViewColors;
  renderThumb?: RenderFileThumb<Extra>;
};

/**
 * The square picture of a file: its thumbnail, or an icon for what kind of file it is, with the
 * download pie over it while it is arriving and a tick when it is chosen.
 */
export function FileThumb<Extra = unknown>({
  item,
  size,
  radius = Math.round(size * 0.2),
  colors = DARK_FILE_VIEW_COLORS,
  renderThumb,
}: FileThumbProps<Extra>) {
  const own = renderThumb ? renderThumb(item, size) : null;
  const tick = Math.max(14, Math.round(size * 0.3));
  return (
    <View style={{ width: size, height: size }}>
      <View
        style={[
          styles.thumb,
          {
            width: size,
            height: size,
            borderRadius: radius,
            backgroundColor: colors.tile,
          },
        ]}
      >
        {own ??
          (item.thumbnail ? (
            <Image source={{ uri: item.thumbnail }} style={styles.cover} resizeMode="cover" />
          ) : (
            <FileViewIcon name={KIND_ICON[item.kind]} size={Math.round(size * 0.58)} color={colors.glyph} />
          ))}
        {item.download != null ? <DownloadPie fraction={item.download} size={size} radius={radius} /> : null}
      </View>
      {item.selected ? (
        <View
          style={[
            styles.tick,
            {
              width: tick,
              height: tick,
              borderRadius: tick / 2,
              backgroundColor: colors.accent,
            },
          ]}
        >
          <FileViewIcon name="tick" size={Math.round(tick * 0.62)} color={colors.onAccent} />
        </View>
      ) : null}
    </View>
  );
}

// ---------------------------------------------------------------------------------------------
// The three shapes
// ---------------------------------------------------------------------------------------------

export type FileRowProps<Extra = unknown> = {
  item: FileViewItem<Extra>;
  colors?: FileViewColors;
  onPress?: () => void;
  /** A long press: the app's menu for this file. */
  onLongPress?: () => void;
  renderThumb?: RenderFileThumb<Extra>;
};

/**
 * The list view: one tight line, the way Finder lists a folder. A small picture, the name, and
 * the state at the right. Every other line is shaded so the eye can follow a line across.
 */
export function FileListRow<Extra = unknown>({
  item,
  index,
  colors = DARK_FILE_VIEW_COLORS,
  onPress,
  onLongPress,
  renderThumb,
}: FileRowProps<Extra> & { index: number }) {
  return (
    <Pressable
      style={[styles.listRow, index % 2 === 1 && { backgroundColor: colors.stripe }, item.dim && styles.dim]}
      onPress={onPress}
      onLongPress={onLongPress}
      accessibilityRole={item.selected == null ? 'button' : 'checkbox'}
      accessibilityState={item.selected == null ? undefined : { checked: item.selected }}
      accessibilityLabel={spoken(item)}
    >
      <FileThumb item={item} size={LIST_THUMB} radius={5} colors={colors} renderThumb={renderThumb} />
      <Text
        style={[styles.listName, { color: colors.text }]}
        numberOfLines={1}
        ellipsizeMode="middle"
        maxFontSizeMultiplier={1.2}
      >
        {item.name}
      </Text>
      {item.status ? (
        <Text
          style={[styles.listStatus, { color: toneColor(item.tone, colors) }]}
          numberOfLines={1}
          maxFontSizeMultiplier={1.2}
        >
          {item.status}
        </Text>
      ) : null}
    </Pressable>
  );
}

/**
 * The grid view: the picture, then two small lines under it, the name (shortened in the middle
 * so its ending still shows) and the state.
 */
export function FileGridCell<Extra = unknown>({
  item,
  tile,
  colors = DARK_FILE_VIEW_COLORS,
  onPress,
  onLongPress,
  renderThumb,
}: FileRowProps<Extra> & { tile: number }) {
  const text = gridText(tile);
  const state = item.shortStatus ?? item.status ?? ' ';
  // A long state ("Uploading 100%") is shrunk a little to fit rather than cut short. A phone
  // measures the text and does it itself; the web cannot, so it is worked out here.
  const stateSize =
    Platform.OS === 'web' ? fitTextSize(state, tile + GRID_TEXT_SPILL * 2, text.status) : text.status;
  return (
    <Pressable
      style={[{ width: tile }, item.dim && styles.dim]}
      onPress={onPress}
      onLongPress={onLongPress}
      accessibilityRole={item.selected == null ? 'button' : 'checkbox'}
      accessibilityState={item.selected == null ? undefined : { checked: item.selected }}
      accessibilityLabel={spoken(item)}
    >
      <FileThumb item={item} size={tile} colors={colors} renderThumb={renderThumb} />
      <Text
        style={[styles.gridName, { color: colors.text, fontSize: text.name, lineHeight: text.nameLine }]}
        numberOfLines={1}
        ellipsizeMode="middle"
        maxFontSizeMultiplier={1.15}
      >
        {item.name}
      </Text>
      <Text
        style={[
          styles.gridStatus,
          { color: toneColor(item.tone, colors), fontSize: stateSize, lineHeight: text.statusLine },
        ]}
        numberOfLines={1}
        adjustsFontSizeToFit
        minimumFontScale={GRID_STATUS_SHRINK}
        maxFontSizeMultiplier={1.15}
      >
        {state}
      </Text>
    </Pressable>
  );
}

/**
 * The expanded view: a roomy row with a larger picture, the name, and a line under it (the
 * state in its colour, then the detail in grey), and the progress bar under that while a
 * transfer is not finished. An app that already has a row of its own for
 * this view keeps it, and passes it to `FileViews` as `renderExpanded`.
 */
export function FileExpandedRow<Extra = unknown>({
  item,
  divider = true,
  colors = DARK_FILE_VIEW_COLORS,
  onPress,
  onLongPress,
  onMore,
  renderThumb,
}: FileRowProps<Extra> & { divider?: boolean; onMore?: () => void }) {
  const under = item.status ?? item.detail ?? '';
  return (
    <View
      style={[
        styles.expandedOuter,
        divider && {
          borderTopWidth: StyleSheet.hairlineWidth,
          borderTopColor: colors.line,
        },
        item.dim && styles.dim,
      ]}
    >
      <Pressable
        style={styles.expandedRow}
        onPress={onPress}
        onLongPress={onLongPress}
        accessibilityRole={item.selected == null ? 'button' : 'checkbox'}
        accessibilityState={item.selected == null ? undefined : { checked: item.selected }}
        accessibilityLabel={spoken(item)}
      >
        <FileThumb item={item} size={EXPANDED_THUMB} radius={10} colors={colors} renderThumb={renderThumb} />
        <View style={styles.expandedText}>
          <Text
            style={[styles.expandedName, { color: colors.text }]}
            numberOfLines={1}
            ellipsizeMode="middle"
          >
            {item.name}
          </Text>
          {under ? (
            <Text style={[styles.expandedUnder, { color: colors.muted }]} numberOfLines={1}>
              {item.status ? (
                <Text style={{ color: toneColor(item.tone, colors) }}>{item.status}</Text>
              ) : null}
              {item.status && item.detail ? ` · ${item.detail}` : item.status ? null : under}
            </Text>
          ) : null}
          {item.bar ? (
            <ShareProgressBar
              value={item.bar.value}
              look={item.bar.look}
              colors={barColors(colors)}
              style={styles.expandedBar}
            />
          ) : null}
        </View>
      </Pressable>
      {/* Beside the row, not inside it: a button inside a button is not allowed on the web. */}
      {onMore ? (
        <Pressable
          style={styles.more}
          onPress={onMore}
          hitSlop={8}
          accessibilityRole="button"
          accessibilityLabel={`More options for ${item.name}`}
        >
          <FileViewIcon name="more" size={20} color={colors.muted} />
        </Pressable>
      ) : null}
    </View>
  );
}

